     1→package telemetry
     2→
     3→import (
     4→	"context"
     5→	"testing"
     6→
     7→	"github.com/spf13/cobra"
     8→)
     9→
    10→func TestNewClientOptOut(t *testing.T) {
    11→	t.Setenv("ENTIRE_TELEMETRY_OPTOUT", "1")
    12→
    13→	client := NewClient("1.0.0", nil)
    14→
    15→	if _, ok := client.(*NoOpClient); !ok {
    16→		t.Error("ENTIRE_TELEMETRY_OPTOUT=1 should return NoOpClient")
    17→	}
    18→}
    19→
    20→func TestNewClientOptOutWithAnyValue(t *testing.T) {
    21→	t.Setenv("ENTIRE_TELEMETRY_OPTOUT", "yes")
    22→
    23→	client := NewClient("1.0.0", nil)
    24→
    25→	if _, ok := client.(*NoOpClient); !ok {
    26→		t.Error("ENTIRE_TELEMETRY_OPTOUT with any value should return NoOpClient")
    27→	}
    28→}
    29→
    30→func TestNewClientTelemetryDisabledInSettings(t *testing.T) {
    31→	disabled := false
    32→	client := NewClient("1.0.0", &disabled)
