   437→		// Always write to local settings file (create if doesn't exist)
   438→		if err := SaveEntireSettingsLocal(settings); err != nil {
   439→			return fmt.Errorf("failed to save local settings: %w", err)
   440→		}
   441→	}
   442→
   443→	fmt.Fprintln(w, "Entire is now disabled.")
   444→	return nil
   445→}
