    64→				return NewSilentError(errors.New("not a git repository"))
    65→			}
    66→
    67→			if err := validateSetupFlags(useLocalSettings, useProjectSettings); err != nil {
    68→				return err
    69→			}
    70→			// Non-interactive mode if --agent flag is provided
    71→			if agentName != "" {
