   551→// setupClaudeCodeHook sets up Claude Code hooks.
   552→// This is a convenience wrapper that uses the agent package.
   553→// Returns the number of hooks installed (0 if already installed).
   554→func setupClaudeCodeHook(localDev, forceHooks bool) (int, error) {
   555→	ag, err := agent.Get(agent.AgentNameClaudeCode)
   556→	if err != nil {
   557→		return 0, fmt.Errorf("failed to get claude-code agent: %w", err)
   558→	}
   559→
   560→	hookAgent, ok := ag.(agent.HookSupport)
   561→	if !ok {
   562→		return 0, errors.New("claude-code agent does not support hooks")
   563→	}
   564→
   565→	count, err := hookAgent.InstallHooks(localDev, forceHooks)
   566→	if err != nil {
   567→		return 0, fmt.Errorf("failed to install claude-code hooks: %w", err)
   568→	}
   569→
   570→	return count, nil
   571→}
   572→
   573→// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
   574→// If strategyName is provided, it sets the strategy; otherwise uses default.
   575→func setupAgentHooksNonInteractive(agentName, strategyName string, localDev, forceHooks, skipPushSessions, noTelemetry, disableMultisessionWarning bool) error {
   576→	ag, err := agent.Get(agentName)
   577→	if err != nil {
   578→		return fmt.Errorf("unknown agent: %s", agentName)
   579→	}
   580→
   581→	// Check if agent supports hooks
   582→	hookAgent, ok := ag.(agent.HookSupport)
   583→	if !ok {
   584→		return fmt.Errorf("agent %s does not support hooks", agentName)
   585→	}
   586→
   587→	// Install hooks
   588→	count, err := hookAgent.InstallHooks(localDev, forceHooks)
   589→	if err != nil {
   590→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
   591→	}
   592→
   593→	if count == 0 {
   594→		fmt.Printf("Hooks for %s already installed\n", ag.Description())
   595→	} else {
   596→		fmt.Printf("Installed %d hooks for %s\n", count, ag.Description())
   597→	}
   598→
   599→	// Update settings to store the agent choice and strategy
   600→	settings, _ := LoadEntireSettings() //nolint:errcheck // settings defaults are fine
   601→	settings.Agent = agentName
   602→	settings.Enabled = true
   603→	if localDev {
   604→		settings.LocalDev = localDev
   605→	}
   606→
   607→	// Set push_sessions option if --skip-push-sessions flag was provided
   608→	if skipPushSessions {
   609→		if settings.StrategyOptions == nil {
   610→			settings.StrategyOptions = make(map[string]interface{})
   611→		}
   612→		settings.StrategyOptions["push_sessions"] = false
   613→	}
   614→
   615→	// Set disable_multisession_warning option if --disable-multisession-warning flag was provided
   616→	if disableMultisessionWarning {
   617→		if settings.StrategyOptions == nil {
   618→			settings.StrategyOptions = make(map[string]interface{})
   619→		}
   620→		settings.StrategyOptions["disable_multisession_warning"] = true
   621→	}
   622→
   623→	// Set strategy if provided
   624→	if strategyName != "" {
   625→		// Map display name to internal name if needed
   626→		internalStrategy := strategyName
   627→		if mapped, ok := strategyDisplayToInternal[strategyName]; ok {
   628→			internalStrategy = mapped
   629→		}
   630→		// Validate the strategy exists
   631→		if _, err := strategy.Get(internalStrategy); err != nil {
   632→			return fmt.Errorf("unknown strategy: %s (use manual-commit or auto-commit)", strategyName)
   633→		}
   634→		settings.Strategy = internalStrategy
   635→	}
   636→
   637→	// Handle telemetry for non-interactive mode
   638→	if noTelemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
   639→		// --no-telemetry flag always overrides existing setting
   640→		f := false
   641→		settings.Telemetry = &f
   642→	} else if settings.Telemetry == nil {
   643→		// Default to enabled in non-interactive mode (only if not already set)
   644→		t := true
   645→		settings.Telemetry = &t
   646→	}
   647→
   648→	if err := SaveEntireSettings(settings); err != nil {
   649→		return fmt.Errorf("failed to save settings: %w", err)
   650→	}
   651→
   652→	// Install git hooks (always reinstall to ensure they're up-to-date)
   653→	if _, err := strategy.InstallGitHook(true); err != nil {
   654→		return fmt.Errorf("failed to install git hooks: %w", err)
   655→	}
   656→
   657→	// Let the strategy handle its own setup requirements (creates entire/sessions branch, etc.)
   658→	strat, err := strategy.Get(settings.Strategy)
   659→	if err != nil {
   660→		return fmt.Errorf("failed to get strategy: %w", err)
   661→	}
   662→	if err := strat.EnsureSetup(); err != nil {
   663→		return fmt.Errorf("failed to setup strategy: %w", err)
   664→	}
   665→
   666→	return nil
   667→}
   668→
   669→// validateSetupFlags checks that --local and --project flags are not both specified.
   670→func validateSetupFlags(useLocal, useProject bool) error {
   671→	if useLocal && useProject {
   672→		return errors.New("cannot specify both --project and --local")
   673→	}
   674→	return nil
   675→}
   676→
   677→// determineSettingsTarget decides whether to write to settings.local.json based on:
   678→// - Whether settings.json already exists
   679→// - The --local and --project flags
   680→// Returns (useLocal, showNotification).
   681→func determineSettingsTarget(entireDir string, useLocal, useProject bool) (bool, bool) {
   682→	// Explicit --local flag always uses local settings
   683→	if useLocal {
   684→		return true, false
   685→	}
   686→
   687→	// Explicit --project flag always uses project settings
   688→	if useProject {
   689→		return false, false
   690→	}
   691→
   692→	// No flags specified - check if settings file exists
   693→	settingsPath := filepath.Join(entireDir, paths.SettingsFileName)
   694→	if _, err := os.Stat(settingsPath); err == nil {
   695→		// Settings file exists - auto-redirect to local with notification
   696→		return true, true
   697→	}
   698→
   699→	// Settings file doesn't exist - create it
   700→	return false, false
   701→}
   702→
   703→// Settings target options for interactive prompt
   704→const (
   705→	settingsTargetProject = "project"
   706→	settingsTargetLocal   = "local"
   707→)
   708→
   709→// promptSettingsTarget interactively asks the user where to save settings
   710→// when settings.json already exists and no flags were provided.
   711→// Returns (useLocal, error).
   712→func promptSettingsTarget(entireDir string, useLocal, useProject bool) (bool, error) {
   713→	// Explicit --local flag always uses local settings
   714→	if useLocal {
   715→		return true, nil
   716→	}
   717→
   718→	// Explicit --project flag always uses project settings
   719→	if useProject {
   720→		return false, nil
   721→	}
   722→
   723→	// Check if settings file exists
   724→	settingsPath := filepath.Join(entireDir, paths.SettingsFileName)
   725→	if _, err := os.Stat(settingsPath); os.IsNotExist(err) {
   726→		// Settings file doesn't exist - create it (no prompt needed)
   727→		return false, nil
   728→	}
   729→
   730→	// Settings file exists - prompt user
   731→	var selected string
   732→	form := NewAccessibleForm(
   733→		huh.NewGroup(
   734→			huh.NewSelect[string]().
   735→				Title("Project settings already exist. Where should settings be saved?").
   736→				Options(
   737→					huh.NewOption("Update project settings (settings.json)", settingsTargetProject),
   738→					huh.NewOption("Use local settings (settings.local.json, gitignored)", settingsTargetLocal),
   739→				).
   740→				Value(&selected),
   741→		),
   742→	)
   743→
   744→	if err := form.Run(); err != nil {
   745→		return false, fmt.Errorf("selection cancelled: %w", err)
   746→	}
   747→
   748→	return selected == settingsTargetLocal, nil
   749→}
   750→
   751→// setupEntireDirectory creates the .entire directory and gitignore.
   752→// Returns true if the directory was created, false if it already existed.
   753→func setupEntireDirectory() (bool, error) {
   754→	// Get absolute path for the .entire directory
   755→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
   756→	if err != nil {
   757→		entireDirAbs = paths.EntireDir // Fallback to relative
   758→	}
   759→
   760→	// Check if directory already exists
   761→	created := false
   762→	if _, err := os.Stat(entireDirAbs); os.IsNotExist(err) {
   763→		created = true
   764→	}
   765→
   766→	// Create .entire directory
   767→	//nolint:gosec // G301: Project directory needs standard permissions for git
   768→	if err := os.MkdirAll(entireDirAbs, 0o755); err != nil {
   769→		return false, fmt.Errorf("failed to create .entire directory: %w", err)
   770→	}
   771→
   772→	// Create/update .gitignore with all required entries
   773→	if err := strategy.EnsureEntireGitignore(); err != nil {
   774→		return false, fmt.Errorf("failed to setup .gitignore: %w", err)
   775→	}
   776→
   777→	return created, nil
   778→}
   779→
   780→// setupGitHook installs the prepare-commit-msg hook for context trailers.
   781→func setupGitHook() error {
   782→	// Use shared implementation from strategy package
   783→	// The localDev setting is read from settings.json
   784→	_, err := strategy.InstallGitHook(false) // not silent - show output during setup
   785→	if err != nil {
   786→		return fmt.Errorf("failed to install git hook: %w", err)
   787→	}
   788→	return nil
   789→}
   790→
   791→// newSetupGitHookCmd creates the standalone git-hook setup command
   792→func newSetupGitHookCmd() *cobra.Command {
   793→	cmd := &cobra.Command{
   794→		Use:    "git-hook",
   795→		Short:  "Install git hook for session context trailers",
   796→		Hidden: true, // Hidden as it's mainly for testing
   797→		RunE: func(_ *cobra.Command, _ []string) error {
   798→			return setupGitHook()
   799→		},
   800→	}
   801→
   802→	return cmd
   803→}
   804→
   805→// shellCompletionComment is the comment preceding the completion line
   806→const shellCompletionComment = "# Entire CLI shell completion"
   807→
   808→// promptShellCompletion offers to add shell completion to the user's rc file.
   809→// Only prompts if completion is not already configured.
   810→func promptShellCompletion(w io.Writer) error {
   811→	// Get user's home directory
   812→	home, err := os.UserHomeDir()
   813→	if err != nil {
   814→		//nolint:nilerr // Skip silently if we can't determine home - not a fatal error
   815→		return nil
   816→	}
   817→
   818→	// Determine shell and rc file
   819→	shell := os.Getenv("SHELL")
   820→	var rcFile string
   821→	var completionLine string
   822→
   823→	switch {
   824→	case strings.Contains(shell, "zsh"):
   825→		rcFile = filepath.Join(home, ".zshrc")
   826→		completionLine = "source <(entire completion zsh)"
   827→	case strings.Contains(shell, "bash"):
   828→		rcFile = filepath.Join(home, ".bashrc")
   829→		completionLine = "source <(entire completion bash)"
   830→	default:
   831→		return nil // Unsupported shell, skip silently
   832→	}
   833→
   834→	// Check if completion is already configured
   835→	if isCompletionConfigured(rcFile) {
   836→		return nil // Already configured, skip silently
   837→	}
   838→
   839→	// Prompt user with select-style picker (matching other prompts)
   840→	var selected string
   841→	form := NewAccessibleForm(
   842→		huh.NewGroup(
   843→			huh.NewSelect[string]().
   844→				Title("Enable shell completion?").
   845→				Options(
   846→					huh.NewOption("Yes", "yes"),
   847→					huh.NewOption("No", "no"),
   848→				).
   849→				Value(&selected),
   850→		),
   851→	)
   852→
   853→	if err := form.Run(); err != nil {
   854→		//nolint:nilerr // User cancelled - not a fatal error, just skip
   855→		return nil
   856→	}
   857→
   858→	if selected != "yes" {
   859→		return nil
   860→	}
   861→
   862→	// Append completion to rc file
   863→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
   864→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
   865→	}
   866→
   867→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
   868→	fmt.Fprintln(w, "  Run `source "+rcFile+"` or restart your shell to activate")
   869→
   870→	return nil
   871→}
   872→
   873→// isCompletionConfigured checks if shell completion is already in the rc file.
   874→func isCompletionConfigured(rcFile string) bool {
   875→	//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
   876→	content, err := os.ReadFile(rcFile)
   877→	if err != nil {
   878→		return false // File doesn't exist or can't read, treat as not configured
   879→	}
   880→	return strings.Contains(string(content), "entire completion")
   881→}
   882→
   883→// appendShellCompletion adds the completion line to the rc file.
   884→func appendShellCompletion(rcFile, completionLine string) error {
   885→	//nolint:gosec // G302: Shell rc files need 0644 for user readability
   886→	f, err := os.OpenFile(rcFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
   887→	if err != nil {
   888→		return fmt.Errorf("opening file: %w", err)
   889→	}
   890→	defer f.Close()
   891→
   892→	// Add newline, comment, and completion line
   893→	_, err = f.WriteString("\n" + shellCompletionComment + "\n" + completionLine + "\n")
   894→	if err != nil {
   895→		return fmt.Errorf("writing completion: %w", err)
   896→	}
   897→	return nil
   898→}
   899→
   900→// setupShellCompletionNonInteractive adds shell completion without prompting.
   901→// Used when --setup-shell flag is provided.
   902→func setupShellCompletionNonInteractive(w io.Writer) error {
   903→	// Get user's home directory
   904→	home, err := os.UserHomeDir()
   905→	if err != nil {
   906→		return fmt.Errorf("cannot determine home directory: %w", err)
   907→	}
   908→
   909→	// Determine shell and rc file
   910→	shell := os.Getenv("SHELL")
   911→	var rcFile string
   912→	var completionLine string
   913→
   914→	switch {
   915→	case strings.Contains(shell, "zsh"):
   916→		rcFile = filepath.Join(home, ".zshrc")
   917→		completionLine = "source <(entire completion zsh)"
   918→	case strings.Contains(shell, "bash"):
   919→		rcFile = filepath.Join(home, ".bashrc")
   920→		completionLine = "source <(entire completion bash)"
   921→	default:
   922→		return fmt.Errorf("unsupported shell: %s (supported: zsh, bash)", shell)
   923→	}
   924→
   925→	// Check if completion is already configured
   926→	if isCompletionConfigured(rcFile) {
   927→		fmt.Fprintf(w, "✓ Shell completion already configured in %s\n", rcFile)
   928→		return nil
   929→	}
   930→
   931→	// Append completion to rc file
   932→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
   933→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
   934→	}
   935→
   936→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
   937→	fmt.Fprintln(w, "  Run `source "+rcFile+"` or restart your shell to activate")
   938→
   939→	return nil
   940→}
   941→
   942→// promptTelemetryConsent asks the user if they want to enable telemetry.
   943→// It modifies settings.Telemetry based on the user's choice or flags.
   944→// The caller is responsible for saving settings.
   945→func promptTelemetryConsent(settings *EntireSettings, noTelemetryFlag bool) error {
   946→	// Handle --no-telemetry flag first (always overrides existing setting)
   947→	if noTelemetryFlag {
   948→		f := false
   949→		settings.Telemetry = &f
   950→		return nil
   951→	}
   952→
   953→	// Skip if already asked
   954→	if settings.Telemetry != nil {
   955→		return nil
   956→	}
   957→
   958→	// Skip if env var disables telemetry (record as disabled)
   959→	if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
   960→		f := false
   961→		settings.Telemetry = &f
   962→		return nil
   963→	}
   964→
   965→	consent := true // Default to Yes
   966→	form := NewAccessibleForm(
   967→		huh.NewGroup(
   968→			huh.NewConfirm().
   969→				Title("Help improve Entire CLI?").
   970→				Description("Share anonymous usage data. No code or personal info collected.").
   971→				Affirmative("Yes").
   972→				Negative("No").
   973→				Value(&consent),
   974→		),
   975→	)
   976→
   977→	if err := form.Run(); err != nil {
   978→		return fmt.Errorf("telemetry prompt: %w", err)
   979→	}
   980→
   981→	settings.Telemetry = &consent
   982→	return nil
   983→}
