   311→	}
   312→
   313→	// Load existing settings to preserve other options (like strategy_options.push)
   314→	settings, err := LoadEntireSettings()
   315→	if err != nil {
   316→		// If we can't load, start with defaults
   317→		settings = &EntireSettings{}
   318→	}
   319→	// Update the specific fields
   320→	settings.Strategy = internalStrategy
   321→	settings.LocalDev = localDev
   322→	settings.Enabled = true
   323→
   324→	// Set push_sessions option if --skip-push-sessions flag was provided
   325→	if skipPushSessions {
   326→		if settings.StrategyOptions == nil {
   327→			settings.StrategyOptions = make(map[string]interface{})
   328→		}
   329→		settings.StrategyOptions["push_sessions"] = false
   330→	}
   331→
   332→	// Set disable_multisession_warning option if --disable-multisession-warning flag was provided
   333→	if disableMultisessionWarning {
   334→		if settings.StrategyOptions == nil {
   335→			settings.StrategyOptions = make(map[string]interface{})
   336→		}
   337→		settings.StrategyOptions["disable_multisession_warning"] = true
   338→	}
   339→
   340→	// Ask about telemetry consent (only if not already asked)
   341→	if err := promptTelemetryConsent(settings, noTelemetry); err != nil {
   342→		return fmt.Errorf("telemetry consent: %w", err)
   343→	}
   344→
   345→	// Determine which settings file to write to (interactive prompt if settings.json exists)
   346→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
   347→	if err != nil {
   348→		entireDirAbs = paths.EntireDir // Fallback to relative
   349→	}
   350→	shouldUseLocal, err := promptSettingsTarget(entireDirAbs, useLocalSettings, useProjectSettings)
   351→	if err != nil {
   352→		return err
   353→	}
   354→
   355→	if shouldUseLocal {
   356→		if err := SaveEntireSettingsLocal(settings); err != nil {
   357→			return fmt.Errorf("failed to save local settings: %w", err)
   358→		}
   359→		fmt.Fprintln(w, "✓ Local settings saved (.entire/settings.local.json)")
   360→	} else {
   361→		if err := SaveEntireSettings(settings); err != nil {
   362→			return fmt.Errorf("failed to save settings: %w", err)
   363→		}
   364→		fmt.Fprintln(w, "✓ Project settings saved (.entire/settings.json)")
   365→	}
   366→
   367→	// Install git hooks (always reinstall to ensure they're up-to-date)
   368→	gitHooksInstalled, err := strategy.InstallGitHook(true)
   369→	if err != nil {
   370→		return fmt.Errorf("failed to install git hooks: %w", err)
   371→	}
   372→	if gitHooksInstalled > 0 {
   373→		fmt.Fprintln(w, "✓ Git hooks installed")
   374→	} else {
   375→		fmt.Fprintln(w, "✓ Git hooks verified")
   376→	}
   377→
   378→	// Let the strategy handle its own setup requirements
   379→	strat, err := strategy.Get(internalStrategy)
   380→	if err != nil {
   381→		return fmt.Errorf("failed to get strategy: %w", err)
   382→	}
   383→	if err := strat.EnsureSetup(); err != nil {
   384→		return fmt.Errorf("failed to setup strategy: %w", err)
   385→	}
   386→
   387→	// Setup shell completion - either non-interactively (if --setup-shell) or prompt
   388→	if setupShell {
   389→		if err := setupShellCompletionNonInteractive(w); err != nil {
   390→			// Non-fatal - just log and continue
   391→			fmt.Fprintf(w, "Note: Shell completion setup skipped: %v\n", err)
   392→		}
   393→	} else {
   394→		// Offer to setup shell completion (only if not already configured)
   395→		if err := promptShellCompletion(w); err != nil {
   396→			// Non-fatal - just log and continue
   397→			fmt.Fprintf(w, "Note: Shell completion setup skipped: %v\n", err)
   398→		}
   399→	}
   400→
   401→	// Show success message with display name
   402→	fmt.Fprintf(w, "\n✓ %s strategy enabled\n", selectedStrategy)
   403→
   404→	return nil
   405→}
