    30→}
    31→
    32→// contextKey is used for storing the telemetry client in context
    33→type contextKey struct{}
    34→
    35→// WithClient returns a new context with the telemetry client attached
    36→func WithClient(ctx context.Context, client Client) context.Context {
    37→	return context.WithValue(ctx, contextKey{}, client)
    38→}
    39→
    40→// GetClient retrieves the telemetry client from context
    41→//
    42→//nolint:ireturn // Returns interface by design - retrieves from context
    43→func GetClient(ctx context.Context) Client {
    44→	if client, ok := ctx.Value(contextKey{}).(Client); ok {
    45→		return client
    46→	}
    47→	return &NoOpClient{}
    48→}
    49→
    50→// NoOpClient is a no-op implementation for when telemetry is disabled
    51→type NoOpClient struct{}
    52→
    53→func (n *NoOpClient) TrackCommand(_ *cobra.Command) {}
    54→func (n *NoOpClient) Close()                        {}
    55→
    56→// silentLogger suppresses PostHog log output - expected for CLI best-effort telemetry
    57→type silentLogger struct{}
    58→
    59→func (silentLogger) Logf(_ string, _ ...interface{})   {}
    60→func (silentLogger) Debugf(_ string, _ ...interface{}) {}
    61→func (silentLogger) Warnf(_ string, _ ...interface{})  {}
    62→func (silentLogger) Errorf(_ string, _ ...interface{}) {}
    63→
    64→// PostHogClient is the real telemetry client
    65→type PostHogClient struct {
    66→	client     posthog.Client
    67→	machineID  string
    68→	cliVersion string
    69→	mu         sync.RWMutex
    70→}
    71→
    72→// NewClient creates a new telemetry client based on opt-out settings.
    73→// The telemetryEnabled parameter comes from settings; nil means not configured (default to enabled).
    74→//
    75→//nolint:ireturn // Factory function - returns NoOpClient or PostHogClient based on settings
    76→func NewClient(version string, telemetryEnabled *bool) Client {
    77→	// Environment variable takes priority
    78→	if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
    79→		return &NoOpClient{}
    80→	}
    81→
    82→	// Check settings preference (nil = not set, default to enabled)
    83→	if telemetryEnabled != nil && !*telemetryEnabled {
    84→		return &NoOpClient{}
    85→	}
    86→
    87→	id, err := machineid.ProtectedID("entire-cli")
    88→	if err != nil {
    89→		return &NoOpClient{}
    90→	}
    91→
    92→	// Use a fast-timeout HTTP transport for telemetry - we don't want to block CLI exit
    93→	transport := &http.Transport{
    94→		DialContext: (&net.Dialer{
    95→			Timeout: 100 * time.Millisecond,
    96→		}).DialContext,
    97→		TLSHandshakeTimeout:   100 * time.Millisecond,
    98→		ResponseHeaderTimeout: 100 * time.Millisecond,
    99→	}
   100→
   101→	client, err := posthog.NewWithConfig(PostHogAPIKey, posthog.Config{
   102→		Endpoint:           PostHogEndpoint,
   103→		ShutdownTimeout:    100 * time.Millisecond, // Don't block CLI exit waiting for telemetry
   104→		BatchUploadTimeout: 200 * time.Millisecond, // Fast timeout - telemetry is best-effort
   105→		Transport:          transport,
   106→		Logger:             silentLogger{}, // Suppress warnings on timeout (expected)
   107→		DisableGeoIP:       posthog.Ptr(true),
   108→		DefaultEventProperties: posthog.NewProperties().
   109→			Set("cli_version", version).
   110→			Set("os", runtime.GOOS).
