   805→// shellCompletionComment is the comment preceding the completion line
   806→const shellCompletionComment = "# Entire CLI shell completion"
   807→
   808→// promptShellCompletion offers to add shell completion to the user's rc file.
   809→// Only prompts if completion is not already configured.
   810→func promptShellCompletion(w io.Writer) error {
   811→	// Get user's home directory
   812→	home, err := os.UserHomeDir()
   813→	if err != nil {
   814→		//nolint:nilerr // Skip silently if we can't determine home - not a fatal error
   815→		return nil
   816→	}
   817→
   818→	// Determine shell and rc file
   819→	shell := os.Getenv("SHELL")
   820→	var rcFile string
   821→	var completionLine string
   822→
   823→	switch {
   824→	case strings.Contains(shell, "zsh"):
   825→		rcFile = filepath.Join(home, ".zshrc")
   826→		completionLine = "source <(entire completion zsh)"
   827→	case strings.Contains(shell, "bash"):
   828→		rcFile = filepath.Join(home, ".bashrc")
   829→		completionLine = "source <(entire completion bash)"
   830→	default:
   831→		return nil // Unsupported shell, skip silently
   832→	}
   833→
   834→	// Check if completion is already configured
   835→	if isCompletionConfigured(rcFile) {
   836→		return nil // Already configured, skip silently
   837→	}
   838→
   839→	// Prompt user with select-style picker (matching other prompts)
   840→	var selected string
   841→	form := NewAccessibleForm(
   842→		huh.NewGroup(
   843→			huh.NewSelect[string]().
   844→				Title("Enable shell completion?").
   845→				Options(
   846→					huh.NewOption("Yes", "yes"),
   847→					huh.NewOption("No", "no"),
   848→				).
   849→				Value(&selected),
   850→		),
   851→	)
   852→
   853→	if err := form.Run(); err != nil {
   854→		//nolint:nilerr // User cancelled - not a fatal error, just skip
   855→		return nil
   856→	}
   857→
   858→	if selected != "yes" {
   859→		return nil
   860→	}
   861→
   862→	// Append completion to rc file
   863→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
   864→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
   865→	}
   866→
   867→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
   868→	fmt.Fprintln(w, "  Run `source "+rcFile+"` or restart your shell to activate")
   869→
   870→	return nil
   871→}
   872→
   873→// isCompletionConfigured checks if shell completion is already in the rc file.
   874→func isCompletionConfigured(rcFile string) bool {
   875→	//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
   876→	content, err := os.ReadFile(rcFile)
   877→	if err != nil {
   878→		return false // File doesn't exist or can't read, treat as not configured
   879→	}
   880→	return strings.Contains(string(content), "entire completion")
   881→}
   882→
   883→// appendShellCompletion adds the completion line to the rc file.
   884→func appendShellCompletion(rcFile, completionLine string) error {
   885→	//nolint:gosec // G302: Shell rc files need 0644 for user readability
   886→	f, err := os.OpenFile(rcFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
   887→	if err != nil {
   888→		return fmt.Errorf("opening file: %w", err)
   889→	}
   890→	defer f.Close()
   891→
   892→	// Add newline, comment, and completion line
   893→	_, err = f.WriteString("\n" + shellCompletionComment + "\n" + completionLine + "\n")
   894→	if err != nil {
   895→		return fmt.Errorf("writing completion: %w", err)
   896→	}
   897→	return nil
   898→}
   899→
   900→// setupShellCompletionNonInteractive adds shell completion without prompting.
   901→// Used when --setup-shell flag is provided.
   902→func setupShellCompletionNonInteractive(w io.Writer) error {
   903→	// Get user's home directory
   904→	home, err := os.UserHomeDir()
   905→	if err != nil {
   906→		return fmt.Errorf("cannot determine home directory: %w", err)
   907→	}
   908→
   909→	// Determine shell and rc file
   910→	shell := os.Getenv("SHELL")
   911→	var rcFile string
   912→	var completionLine string
   913→
   914→	switch {
   915→	case strings.Contains(shell, "zsh"):
   916→		rcFile = filepath.Join(home, ".zshrc")
   917→		completionLine = "source <(entire completion zsh)"
   918→	case strings.Contains(shell, "bash"):
   919→		rcFile = filepath.Join(home, ".bashrc")
   920→		completionLine = "source <(entire completion bash)"
   921→	default:
   922→		return fmt.Errorf("unsupported shell: %s (supported: zsh, bash)", shell)
   923→	}
   924→
   925→	// Check if completion is already configured
   926→	if isCompletionConfigured(rcFile) {
   927→		fmt.Fprintf(w, "✓ Shell completion already configured in %s\n", rcFile)
   928→		return nil
   929→	}
   930→
   931→	// Append completion to rc file
   932→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
   933→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
   934→	}
   935→
   936→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
   937→	fmt.Fprintln(w, "  Run `source "+rcFile+"` or restart your shell to activate")
   938→
   939→	return nil
   940→}
   941→
   942→// promptTelemetryConsent asks the user if they want to enable telemetry.
   943→// It modifies settings.Telemetry based on the user's choice or flags.
   944→// The caller is responsible for saving settings.
   945→func promptTelemetryConsent(settings *EntireSettings, noTelemetryFlag bool) error {
   946→	// Handle --no-telemetry flag first (always overrides existing setting)
   947→	if noTelemetryFlag {
   948→		f := false
   949→		settings.Telemetry = &f
   950→		return nil
   951→	}
   952→
   953→	// Skip if already asked
   954→	if settings.Telemetry != nil {
   955→		return nil
   956→	}
   957→
   958→	// Skip if env var disables telemetry (record as disabled)
   959→	if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
   960→		f := false
   961→		settings.Telemetry = &f
   962→		return nil
   963→	}
   964→
   965→	consent := true // Default to Yes
   966→	form := NewAccessibleForm(
   967→		huh.NewGroup(
   968→			huh.NewConfirm().
   969→				Title("Help improve Entire CLI?").
   970→				Description("Share anonymous usage data. No code or personal info collected.").
   971→				Affirmative("Yes").
   972→				Negative("No").
   973→				Value(&consent),
   974→		),
   975→	)
   976→
   977→	if err := form.Run(); err != nil {
   978→		return fmt.Errorf("telemetry prompt: %w", err)
   979→	}
   980→
   981→	settings.Telemetry = &consent
   982→	return nil
   983→}
