   273→	}
   274→
   275→	form := NewAccessibleForm(
   276→		huh.NewGroup(
   277→			huh.NewSelect[string]().
   278→				Options(options...).
   279→				Value(&selectedStrategy),
   280→		),
   281→	)
   282→
   283→	if err := form.Run(); err != nil {
   284→		return fmt.Errorf("selection cancelled: %w", err)
   285→	}
   286→
   287→	// Map display name to internal strategy name
   288→	internalStrategy, ok := strategyDisplayToInternal[selectedStrategy]
