   423→func runDisable(w io.Writer, useProjectSettings bool) error {
   424→	settings, err := LoadEntireSettings()
   425→	if err != nil {
   426→		return fmt.Errorf("failed to load settings: %w", err)
   427→	}
   428→
   429→	settings.Enabled = false
   430→
   431→	// If --project flag is specified, always write to project settings
   432→	if useProjectSettings {
   433→		if err := SaveEntireSettings(settings); err != nil {
   434→			return fmt.Errorf("failed to save settings: %w", err)
   435→		}
   436→	} else {
   437→		// Always write to local settings file (create if doesn't exist)
   438→		if err := SaveEntireSettingsLocal(settings); err != nil {
   439→			return fmt.Errorf("failed to save local settings: %w", err)
   440→		}
   441→	}
   442→
   443→	fmt.Fprintln(w, "Entire is now disabled.")
   444→	return nil
   445→}
