   266→// runEnableInteractive runs the interactive enable flow with strategy selection.
   267→func runEnableInteractive(w io.Writer, localDev, _, useLocalSettings, useProjectSettings, forceHooks, setupShell, skipPushSessions, noTelemetry, disableMultisessionWarning bool) error {
   268→	// Build strategy options with user-friendly names
   269→	var selectedStrategy string
   270→	options := []huh.Option[string]{
   271→		huh.NewOption(strategyDisplayManualCommit+"  Sessions are only captured when you commit", strategyDisplayManualCommit),
   272→		huh.NewOption(strategyDisplayAutoCommit+"  Automatically capture sessions after agent response completion", strategyDisplayAutoCommit),
   273→	}
   274→
   275→	form := NewAccessibleForm(
   276→		huh.NewGroup(
   277→			huh.NewSelect[string]().
   278→				Options(options...).
   279→				Value(&selectedStrategy),
   280→		),
   281→	)
   282→
   283→	if err := form.Run(); err != nil {
   284→		return fmt.Errorf("selection cancelled: %w", err)
   285→	}
