    72→// NewClient creates a new telemetry client based on opt-out settings.
    73→// The telemetryEnabled parameter comes from settings; nil means not configured (default to enabled).
    74→//
    75→//nolint:ireturn // Factory function - returns NoOpClient or PostHogClient based on settings
    76→func NewClient(version string, telemetryEnabled *bool) Client {
