   134→// runEnableWithStrategy enables Entire with a specified strategy (non-interactive).
   135→// The selectedStrategy can be either a display name (manual-commit, auto-commit)
   136→// or an internal name (manual-commit, auto-commit).
   137→func runEnableWithStrategy(w io.Writer, selectedStrategy string, localDev, _, useLocalSettings, useProjectSettings, forceHooks, setupShell, skipPushSessions, noTelemetry bool, disableMultisessionWarning bool) error {
   138→	// Map the strategy to internal name if it's a display name
   139→	internalStrategy := selectedStrategy
   140→	if mapped, ok := strategyDisplayToInternal[selectedStrategy]; ok {
   141→		internalStrategy = mapped
   142→	}
   143→
   144→	// Validate the strategy exists
   145→	strat, err := strategy.Get(internalStrategy)
   146→	if err != nil {
   147→		return fmt.Errorf("unknown strategy: %s (use manual-commit or auto-commit)", selectedStrategy)
   148→	}
   149→
   150→	// Setup Claude Code hooks
   151→	hooksInstalled, err := setupClaudeCodeHook(localDev, forceHooks)
   152→	if err != nil {
   153→		return fmt.Errorf("failed to setup Claude Code hooks: %w", err)
   154→	}
   155→	if hooksInstalled > 0 {
   156→		fmt.Fprintln(w, "✓ Claude Code hooks installed")
   157→	} else {
   158→		fmt.Fprintln(w, "✓ Claude Code hooks verified")
   159→	}
   160→
   161→	// Setup .entire directory
   162→	dirCreated, err := setupEntireDirectory()
   163→	if err != nil {
   164→		return fmt.Errorf("failed to setup .entire directory: %w", err)
   165→	}
   166→	if dirCreated {
   167→		fmt.Fprintln(w, "✓ .entire directory created")
   168→	}
   169→
   170→	// Load existing settings to preserve other options (like strategy_options.push)
   171→	settings, err := LoadEntireSettings()
   172→	if err != nil {
   173→		// If we can't load, start with defaults
   174→		settings = &EntireSettings{}
   175→	}
   176→	// Update the specific fields
   177→	settings.Strategy = internalStrategy
   178→	settings.LocalDev = localDev
   179→	settings.Enabled = true
   180→
   181→	// Set push_sessions option if --skip-push-sessions flag was provided
   182→	if skipPushSessions {
   183→		if settings.StrategyOptions == nil {
   184→			settings.StrategyOptions = make(map[string]interface{})
   185→		}
   186→		settings.StrategyOptions["push_sessions"] = false
   187→	}
   188→
   189→	// Set disable_multisession_warning option if --disable-multisession-warning flag was provided
   190→	if disableMultisessionWarning {
   191→		if settings.StrategyOptions == nil {
   192→			settings.StrategyOptions = make(map[string]interface{})
   193→		}
   194→		settings.StrategyOptions["disable_multisession_warning"] = true
   195→	}
   196→
   197→	// Handle telemetry for non-interactive mode
   198→	if noTelemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
   199→		// --no-telemetry flag always overrides existing setting
   200→		f := false
   201→		settings.Telemetry = &f
   202→	} else if settings.Telemetry == nil {
   203→		// Default to enabled in non-interactive mode (only if not already set)
   204→		t := true
   205→		settings.Telemetry = &t
   206→	}
   207→
   208→	// Determine which settings file to write to
   209→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
   210→	if err != nil {
   211→		entireDirAbs = paths.EntireDir // Fallback to relative
   212→	}
   213→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, useLocalSettings, useProjectSettings)
   214→
   215→	if showNotification {
   216→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
   217→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
   218→	}
   219→
   220→	if shouldUseLocal {
   221→		if err := SaveEntireSettingsLocal(settings); err != nil {
   222→			return fmt.Errorf("failed to save local settings: %w", err)
   223→		}
   224→		fmt.Fprintln(w, "✓ Local settings saved (.entire/settings.local.json)")
   225→	} else {
   226→		if err := SaveEntireSettings(settings); err != nil {
   227→			return fmt.Errorf("failed to save settings: %w", err)
   228→		}
   229→		fmt.Fprintln(w, "✓ Project settings saved (.entire/settings.json)")
   230→	}
   231→
   232→	// Install git hooks (always reinstall to ensure they're up-to-date)
   233→	gitHooksInstalled, err := strategy.InstallGitHook(true)
   234→	if err != nil {
   235→		return fmt.Errorf("failed to install git hooks: %w", err)
   236→	}
   237→	if gitHooksInstalled > 0 {
   238→		fmt.Fprintln(w, "✓ Git hooks installed")
   239→	} else {
   240→		fmt.Fprintln(w, "✓ Git hooks verified")
   241→	}
   242→
   243→	// Let the strategy handle its own setup requirements
   244→	if err := strat.EnsureSetup(); err != nil {
   245→		return fmt.Errorf("failed to setup strategy: %w", err)
   246→	}
   247→
   248→	// Setup shell completion if --setup-shell flag was provided
   249→	if setupShell {
   250→		if err := setupShellCompletionNonInteractive(w); err != nil {
   251→			// Non-fatal - just log and continue
   252→			fmt.Fprintf(w, "Note: Shell completion setup skipped: %v\n", err)
   253→		}
   254→	}
   255→
   256→	// Show success message with display name
   257→	displayName := selectedStrategy
   258→	if dn, ok := strategyInternalToDisplay[internalStrategy]; ok {
   259→		displayName = dn
   260→	}
   261→	fmt.Fprintf(w, "\n✓ %s strategy enabled\n", displayName)
   262→
   263→	return nil
   264→}
   265→
   266→// runEnableInteractive runs the interactive enable flow with strategy selection.
   267→func runEnableInteractive(w io.Writer, localDev, _, useLocalSettings, useProjectSettings, forceHooks, setupShell, skipPushSessions, noTelemetry, disableMultisessionWarning bool) error {
   268→	// Build strategy options with user-friendly names
   269→	var selectedStrategy string
   270→	options := []huh.Option[string]{
   271→		huh.NewOption(strategyDisplayManualCommit+"  Sessions are only captured when you commit", strategyDisplayManualCommit),
   272→		huh.NewOption(strategyDisplayAutoCommit+"  Automatically capture sessions after agent response completion", strategyDisplayAutoCommit),
   273→	}
   274→
   275→	form := NewAccessibleForm(
   276→		huh.NewGroup(
   277→			huh.NewSelect[string]().
   278→				Options(options...).
   279→				Value(&selectedStrategy),
   280→		),
   281→	)
   282→
   283→	if err := form.Run(); err != nil {
   284→		return fmt.Errorf("selection cancelled: %w", err)
   285→	}
   286→
   287→	// Map display name to internal strategy name
   288→	internalStrategy, ok := strategyDisplayToInternal[selectedStrategy]
   289→	if !ok {
   290→		return fmt.Errorf("unknown strategy: %s", selectedStrategy)
   291→	}
   292→
   293→	// Setup Claude Code hooks
   294→	hooksInstalled, err := setupClaudeCodeHook(localDev, forceHooks)
   295→	if err != nil {
   296→		return fmt.Errorf("failed to setup Claude Code hooks: %w", err)
   297→	}
   298→	if hooksInstalled > 0 {
   299→		fmt.Fprintln(w, "✓ Claude Code hooks installed")
   300→	} else {
   301→		fmt.Fprintln(w, "✓ Claude Code hooks verified")
   302→	}
   303→
   304→	// Setup .entire directory
   305→	dirCreated, err := setupEntireDirectory()
   306→	if err != nil {
   307→		return fmt.Errorf("failed to setup .entire directory: %w", err)
   308→	}
   309→	if dirCreated {
   310→		fmt.Fprintln(w, "✓ .entire directory created")
   311→	}
   312→
   313→	// Load existing settings to preserve other options (like strategy_options.push)
   314→	settings, err := LoadEntireSettings()
   315→	if err != nil {
   316→		// If we can't load, start with defaults
   317→		settings = &EntireSettings{}
   318→	}
   319→	// Update the specific fields
   320→	settings.Strategy = internalStrategy
   321→	settings.LocalDev = localDev
   322→	settings.Enabled = true
   323→
   324→	// Set push_sessions option if --skip-push-sessions flag was provided
   325→	if skipPushSessions {
   326→		if settings.StrategyOptions == nil {
   327→			settings.StrategyOptions = make(map[string]interface{})
   328→		}
   329→		settings.StrategyOptions["push_sessions"] = false
   330→	}
   331→
   332→	// Set disable_multisession_warning option if --disable-multisession-warning flag was provided
   333→	if disableMultisessionWarning {
   334→		if settings.StrategyOptions == nil {
   335→			settings.StrategyOptions = make(map[string]interface{})
   336→		}
   337→		settings.StrategyOptions["disable_multisession_warning"] = true
   338→	}
   339→
   340→	// Ask about telemetry consent (only if not already asked)
   341→	if err := promptTelemetryConsent(settings, noTelemetry); err != nil {
   342→		return fmt.Errorf("telemetry consent: %w", err)
   343→	}
   344→
   345→	// Determine which settings file to write to (interactive prompt if settings.json exists)
   346→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
   347→	if err != nil {
   348→		entireDirAbs = paths.EntireDir // Fallback to relative
   349→	}
   350→	shouldUseLocal, err := promptSettingsTarget(entireDirAbs, useLocalSettings, useProjectSettings)
   351→	if err != nil {
   352→		return err
   353→	}
   354→
   355→	if shouldUseLocal {
   356→		if err := SaveEntireSettingsLocal(settings); err != nil {
   357→			return fmt.Errorf("failed to save local settings: %w", err)
   358→		}
   359→		fmt.Fprintln(w, "✓ Local settings saved (.entire/settings.local.json)")
   360→	} else {
   361→		if err := SaveEntireSettings(settings); err != nil {
   362→			return fmt.Errorf("failed to save settings: %w", err)
   363→		}
   364→		fmt.Fprintln(w, "✓ Project settings saved (.entire/settings.json)")
   365→	}
   366→
   367→	// Install git hooks (always reinstall to ensure they're up-to-date)
   368→	gitHooksInstalled, err := strategy.InstallGitHook(true)
   369→	if err != nil {
   370→		return fmt.Errorf("failed to install git hooks: %w", err)
   371→	}
   372→	if gitHooksInstalled > 0 {
   373→		fmt.Fprintln(w, "✓ Git hooks installed")
   374→	} else {
   375→		fmt.Fprintln(w, "✓ Git hooks verified")
   376→	}
   377→
   378→	// Let the strategy handle its own setup requirements
   379→	strat, err := strategy.Get(internalStrategy)
   380→	if err != nil {
   381→		return fmt.Errorf("failed to get strategy: %w", err)
   382→	}
   383→	if err := strat.EnsureSetup(); err != nil {
   384→		return fmt.Errorf("failed to setup strategy: %w", err)
   385→	}
   386→
   387→	// Setup shell completion - either non-interactively (if --setup-shell) or prompt
   388→	if setupShell {
   389→		if err := setupShellCompletionNonInteractive(w); err != nil {
   390→			// Non-fatal - just log and continue
   391→			fmt.Fprintf(w, "Note: Shell completion setup skipped: %v\n", err)
   392→		}
   393→	} else {
   394→		// Offer to setup shell completion (only if not already configured)
   395→		if err := promptShellCompletion(w); err != nil {
   396→			// Non-fatal - just log and continue
   397→			fmt.Fprintf(w, "Note: Shell completion setup skipped: %v\n", err)
   398→		}
   399→	}
   400→
   401→	// Show success message with display name
   402→	fmt.Fprintf(w, "\n✓ %s strategy enabled\n", selectedStrategy)
   403→
   404→	return nil
   405→}
