    54→		Short: "Enable Entire",
    55→		Long:  "Enable Entire with interactive setup for session tracking mode",
    56→		RunE: func(cmd *cobra.Command, _ []string) error {
    57→			// Check if we're in a git repository first - this is a prerequisite error,
    58→			// not a usage error, so we silence Cobra's output and use SilentError
    59→			// to prevent duplicate error output in main.go
